    fn render_output(&self, cx: &mut Context<Self>) -> AnyElement {
        let Some(task) = self.tasks.last() else {
            return div().into_any_element();
        };
        let task_ix = self.tasks.len() - 1;
        let rows = task.reply.rows();
        let count = rows.len();
        // What the last rows, which stream, show, so they're remeasured only
        // when that changes; remeasuring has the list go over every row.
        let streaming = {
            use std::hash::{Hash as _, Hasher as _};
            let mut hasher = std::collections::hash_map::DefaultHasher::new();
            for row in &rows[count.saturating_sub(2)..] {
                match row {
                    OutputRow::Text(text) => (0, *text).hash(&mut hasher),
                    OutputRow::Error(text) => (1, *text).hash(&mut hasher),
                    OutputRow::Tool(call) => {
                        (2, &call.name, &call.summary, call.state as u8).hash(&mut hasher)
                    }
                    OutputRow::Pending => 3.hash(&mut hasher),
                }
            }
            hasher.finish()
        };
        drop(rows);
        // Only the rows in view are laid out, so drawing it costs the same
        // however long the output grows. The list is told when the task
        // changes, when rows come or go, and that the last rows, which
        // stream, may have changed height.
        let (laid_out_task, laid_out_count, laid_out_streaming) = self.output_list_for.get();
        if laid_out_task != task.uid {
            self.output_list.reset(count);
        } else if laid_out_count != count {
            self.output_list.splice(
                laid_out_count.min(count)..laid_out_count,
                count - laid_out_count.min(count),
            );
            scrollbar::measure_new_rows(&self.output_list);
        }
        self.output_list_for.set((task.uid, count, streaming));
        // Its markdown's states are kept, so rows measure as tall out of view
        // as in it: all of them when the task or its rows change, and the last
        // rows as they stream.
        let changed_rows = if laid_out_task != task.uid || laid_out_count != count {
            Some(0..count)
        } else {
            (streaming != laid_out_streaming).then(|| count.saturating_sub(2)..count)
        };
        if let Some(rows) = changed_rows {
            let project_dir = ProjectDirectory::get(cx);
            for (key, text) in task_markdown(task_ix, task, rows, false, project_dir.as_deref()) {
                MarkdownStates::prepare(key, &text, cx);
            }
        }
        if count > 0 && streaming != laid_out_streaming {
            self.output_list
                .remeasure_items(count.saturating_sub(2)..count);
        }
        if self.output_locked {
            self.output_list.scroll_to_end();
        }

        let theme = cx.theme();
        let content = if count == 0 {
            div()
                .p_4()
                .text_color(theme.muted_foreground)
                .child("No output.")
                .into_any_element()
        } else {
            let this = cx.entity().downgrade();
            let open = self.file_opener(cx);
            let border = theme.border;
            let rows = list(self.output_list.clone(), move |row_ix, _, cx| {
                let Some(this) = this.upgrade() else {
                    return div().into_any_element();
                };
                let this = this.read(cx);
                let Some(task) = this.tasks.get(task_ix) else {
                    return div().into_any_element();
                };
                let rows = task.reply.rows();
                let Some(row) = rows.get(row_ix) else {
                    return div().into_any_element();
                };
                let project_dir = ProjectDirectory::get(cx);
                div()
                    .when(row_ix > 0, |row| row.border_t_1().border_color(border))
                    .child(output_row(
                        task_ix,
                        &task.reply,
                        row_ix,
                        row,
                        Some(&open),
                        project_dir.as_deref(),
                        cx,
                    ))
                    .into_any_element()
            })
            .size_full();
            // A table, as elsewhere, with its header kept above the rows as
            // they scroll.
            v_flex()
                .size_full()
                .overflow_hidden()
                .text_base()
                .line_height(relative(1.5))
                .rounded(theme.radius)
                .border_1()
                .border_color(theme.border)
                .bg(theme.tokens.table)
                .child(output_header(cx))
                .child(div().flex_1().min_h_0().child(rows))
                .into_any_element()
        };
        let output = div().id("task-output").size_full().p_4().child(content);
        // Lets UI tests find the output; inert in normal builds.
        let output = gpui_kit::TestSupportExt::test_support(output);
        let this = cx.entity().downgrade();
        let toggle: SetLock = Rc::new(move |locked, _, cx| {
            this.update(cx, |this, cx| this.set_output_lock(locked, cx))
                .ok();
        });
        scrollbar::with_scrollbar(
            "task-output",
            &self.output_list,
            output,
            true,
            Some((self.output_locked, toggle)),
            cx,
        )
    }
}

impl PromptMode {
    /// Keeps the markdown states of the open previous task and answer, and
    /// has each list measure again a row whose markdown finished parsing
    /// since it was last measured (see [`MarkdownStates`]).
    fn keep_markdown(&self, cx: &mut Context<Self>) {
        let project_dir = ProjectDirectory::get(cx);
        let lists = [
            (&self.task_history, &self.tasks),
            (&self.ask_history, &self.answers),
        ];
        for (history, tasks) in lists {
            let Some(open) = history.open.filter(|_| history.expanded) else {
                continue;
            };
            if let Some(task) = tasks.get(open) {
                let rows = 0..task.reply.rows().len();
                let pieces = task_markdown(
                    history.id_base + open,
                    task,
                    rows,
                    true,
                    project_dir.as_deref(),
                );
                for (key, text) in pieces {
                    MarkdownStates::prepare(key, &text, cx);
                }
            }
        }
        let latest = self.tasks.len().checked_sub(1);
        for key in MarkdownStates::take_changed(cx) {
            if Some(key.table) == latest && key.kind != MarkdownKind::Prompt {
                self.output_list.remeasure_items(key.row..key.row + 1);
                scrollbar::measure_new_rows(&self.output_list);
            }
            for history in [&self.task_history, &self.ask_history] {
                if let Some(open) = history.open
                    && key.table == history.id_base + open
                {
                    history.scroll.remeasure_items(open..open + 1);
                    scrollbar::measure_new_rows(&history.scroll);
                }
            }
        }
    }
}

impl Render for PromptMode {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        self.keep_markdown(cx);
        // The popover for text selected in an answer goes with the drawer.
        if !self.drawer_open() {
            self.selection_popover = None;
        }
        let hint = if ProjectDirectory::get(cx).is_some() {
            "Write a prompt below. Enter adds a line; Ctrl/Cmd+Enter sends it."
        } else {
            "Open a project to start prompting."
        };

        let content = if self.tasks.is_empty() {
            // The hint may shrink below one line, so it wraps in a narrow view
            // instead of running past its edges.
            let hint = div()
                .id("history-hint")
                .min_w_0()
                .text_center()
                .child(Label::new(hint));
            div()
                .flex_1()
                .flex()
                .items_center()
                .justify_center()
                .px_4()
                // Lets UI tests find the hint; inert in normal builds.
                .child(gpui_kit::TestSupportExt::test_support(hint))
                .into_any_element()
        } else if self.task_history.expanded {
            let open_file = self.file_opener(cx);
            self.task_history.render_list(
                |this| &this.tasks,
                self.tasks.len(),
                |this| &mut this.task_history,
                &open_file,
                cx,
            )
        } else {
            self.render_output(cx)
        };

        let history = v_flex()
            .id("history")
            .size_full()
            .child(self.task_history.render_row(
                // The latest task heads the view, so it isn't counted.
                self.tasks.len().saturating_sub(1),
                !self.tasks.is_empty(),
                |this| &mut this.task_history,
                cx,
            ))
            .children(self.render_header(cx))
            .child(content)
            .children(self.render_queue(cx));
        // Lets UI tests find the history; inert in normal builds.
        let history = gpui_kit::TestSupportExt::test_support(history);
        let history = div().relative().size_full().child(history);

        // The task view, and any file split off it.
        let body = div().relative().flex_1().min_h_0().on_prepaint({
            let body_width = self.body_width.clone();
            move |bounds, _, _| body_width.set(bounds.size.width)
        });
        // A file split off beside the task view, which can't be dragged
        // narrower than its editor's 80 columns.
        let pane = self
            .file
            .as_ref()
            .map(|file| (file.clone(), file.read(cx).min_width(window, cx)));
        // The width the pane opens at: its share of the body, or its narrowest.
        let pane_width = |file_min: Pixels| {
            if self.body_width.get() > px(0.) {
                (self.body_width.get() * FILE_SHARE).max(file_min)
            } else {
                file_min
            }
        };
        let sliding = self
            .pane_opened
            .filter(|(_, opened)| opened.elapsed() < PANE_SLIDE_TIME)
            .map(|(n, _)| n);
        if self
            .pane_closing
            .as_ref()
            .is_some_and(|closing| closing.closed.elapsed() >= PANE_SLIDE_TIME)
        {
            self.pane_closing = None;
        }
        // Records the pane's width as laid out, for it to slide closed from.
        let measured = |pane: AnyElement| {
            let pane_width = self.pane_width.clone();
            div()
                .size_full()
                .on_prepaint(move |bounds, _, _| pane_width.set(bounds.size.width))
                .child(pane)
        };
        let body = match pane {
            // Just opened, the pane grows out of the sidebar at its left, with
            // the file sliding into view from behind the sidebar's edge, and
            // the task view giving way beside it. Once it has, it is an ordinary
            // split that can be dragged.
            Some((file, file_min)) if sliding.is_some() && self.body_width.get() > px(0.) => {
                window.request_animation_frame();
                let width = pane_width(file_min);
                let grow = SpringAnimation::new(PANE_SPRING).to(width).from(px(0.));
                // Lets UI tests find the pane as it slides; inert in normal
                // builds.
                let pane = gpui_kit::TestSupportExt::test_support(
                    div().id(("pane-slide", sliding.unwrap_or(0))),
                )
                .relative()
                .flex_none()
                .h_full()
                .overflow_hidden()
                .child(
                    div()
                        .absolute()
                        .top_0()
                        .bottom_0()
                        .right_0()
                        .w(width)
                        .child(measured(file.into_any_element())),
                )
                .with_spring(
                    ("pane-grow", sliding.unwrap_or(0)),
                    grow,
                    |this, width| this.w(width.max(px(0.))),
                );
                body.child(
                    h_flex()
                        .size_full()
                        .child(pane)
                        .child(div().flex_1().min_w_0().h_full().child(history)),
                )
            }
            Some((file, file_min)) => {
                let mut file_panel = resizable_panel().size_range(file_min..Pixels::MAX);
                // Not laid out yet: the split starts even, and can be dragged.
                if self.body_width.get() > px(0.) {
                    file_panel =
                        file_panel.size((self.body_width.get() * FILE_SHARE).max(file_min));
                }
                body.child(
                    h_resizable("file-split")
                        .with_state(&self.file_split)
                        .children([
                            file_panel.child(measured(file.into_any_element())),
                            resizable_panel()
                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
                                .child(history),
                        ]),
                )
            }
            // Just closed, the pane shrinks back into the sidebar, with the
            // file sliding out of view behind the sidebar's edge, and the task
            // view growing back beside it.
            None if let Some(closing) = &self.pane_closing => {
                window.request_animation_frame();
                let shrink = SpringAnimation::new(PANE_SPRING)
                    .to(px(0.))
                    .from(closing.width);
                // Lets UI tests find the pane as it slides; inert in normal
                // builds.
                let pane = gpui_kit::TestSupportExt::test_support(
                    div().id(("pane-slide-out", closing.slide)),
                )
                .relative()
                .flex_none()
                .h_full()
                .overflow_hidden()
                .child(
                    div()
                        .absolute()
                        .top_0()
                        .bottom_0()
                        .right_0()
                        .w(closing.width)
                        .child(closing.file.clone()),
                )
                .with_spring(
                    ("pane-shrink", closing.slide),
                    shrink,
                    |this, width| this.w(width.max(px(0.))),
                );
                body.child(
                    h_flex()
                        .size_full()
                        .child(pane)
                        .child(div().flex_1().min_w_0().h_full().child(history)),
                )
            }
            None => body.child(history),
        };
        // Above the chat input: the task view, pushed up by the stack of
        // questions beneath it, with the answer drawer sliding up over both
        // and dimming them.
        let body = div()
            .id("prompt-body")
            .relative()
            .flex_1()
            .min_h_0()
            .on_prepaint({
                let body_height = self.body_height.clone();
                move |bounds, _, _| body_height.set(bounds.size.height)
            })
            // Dragging the answer drawer's top edge resizes it.
            .on_drag_move(
                cx.listener(|this, event: &DragMoveEvent<DrawerResize>, _, cx| {
                    this.drag_drawer(event.event.position.y, event.bounds, cx)
                }),
            )
            .child(
                v_flex()
                    .size_full()
                    .child(body)
                    .children(self.render_ask_stack(cx)),
            )
            .child(self.render_ask_dim(cx))
            .children(self.render_ask_drawer(cx))
            .children(self.render_selection_popover(cx));
        // Lets UI tests find the space above the chat input; inert in normal
        // builds.
        let body = gpui_kit::TestSupportExt::test_support(body);

        v_flex()
            .size_full()
            .child(body)
            .child(self.chat_input.clone())
    }
}

