    steps_shown: HashSet<usize>,
    answers: Vec<PromptTask>,
    ask_history: HistoryList,
    _ask_history_load: Task<()>,
    ask_session: Option<Session>,
}

impl ProjectSession {
    fn new(project_dir: Option<PathBuf>) -> Self {
        Self {
            project_dir,
            tasks: Vec::new(),
            working: false,
