        } else {
            sum / count as f32
        }
    }

    fn record(&mut self, ix: usize, height: Pixels) {
        let Some(row) = self.rows.get_mut(ix) else {
            return;
        };
        if row.height != height {
            self.tops_stale = true;
        }
        *row = RowHeight {
            height,
            exact: true,
