        if self.tops_stale || self.tops.len() != self.rows.len() + 1 {
            self.tops.clear();
            let mut top = px(0.);
            self.tops.push(top);
            for row in &self.rows {
                top += row.height;
                self.tops.push(top);
            }
            self.tops_stale = false;
        }
        &self.tops
    }
